# Collect target configurations

# Inspect original argv before any supplier configuration is evaluated.
my $foundation_private_requested =
    grep { $_ eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1' } @ARGV;
my $pattern = catfile(dirname($0), "Configurations", "*.conf");
if ($foundation_private_requested) {
    die "foundation profile rejects local configuration injection\n"
        if defined env($local_config_envname)
            || grep { /^OPENSSL_LOCAL_CONFIG_DIR=/ } @ARGV;
    my @foundation_configs =
        map { /^--config=(.*)$/ ? $1 : () } @ARGV;
    die "foundation profile requires one admitted private configuration\n"
        unless @foundation_configs == 1
            && file_name_is_absolute($foundation_configs[0])
            && basename($foundation_configs[0]) eq 'foundation-amd64-static-noasm.conf';
    foreach my $name ('00-base-templates.conf', '10-main.conf') {
        &read_config(catfile(dirname($0), "Configurations", $name));
    }
} else {
    foreach (sort glob($pattern)) {
        &read_config($_);
    }

    if (defined env($local_config_envname)) {
        if ($^O eq 'VMS') {
            # VMS environment variables are logical names,
            # which can be used as is
            $pattern = $local_config_envname . ':' . '*.conf';
        } else {
            $pattern = catfile(env($local_config_envname), '*.conf');
        }

        foreach (sort glob($pattern)) {
            &read_config($_);
        }
    }
}

# Private Foundation dependency profile. This is not an upstream target or
# a claim of LLVM compatibility. Its immutable config and tool closure must
# be admitted independently before this code may run.
my $foundation_static_amd64_noasm =
    $config{target} eq 'VC-FOUNDATION-AMD64-STATIC-NOASM-V1';
if ($foundation_static_amd64_noasm) {
    die "foundation profile requires exact original target argv\n"
        unless $foundation_private_requested;
    die "foundation profile requires native Windows Perl\n" unless $^O eq 'MSWin32';
    foreach my $arg (qw(no-shared no-asm no-uplink no-apps no-docs no-tests no-module no-makedepend --release)) {
        die "foundation profile missing fixed option $arg\n"
            unless grep { $_ eq $arg } @{$config{perlargv}};
    }
    die "foundation profile drift: shared/asm/uplink/build type\n"
        unless $disabled{shared} && $disabled{asm} && $disabled{uplink}
            && $disabled{apps} && $disabled{docs} && $disabled{tests}
            && $disabled{module} && $disabled{makedepend}
            && $config{build_type} eq 'release';
    die "foundation profile drift: architecture/dependency scheme\n"
        if defined($target{asm_arch}) || defined($target{uplink_arch})
            || ($target{makedep_scheme} // '') ne 'VC' || $strict_warnings;
    die "foundation profile drift: build file or preprocessor\n"
        unless ($config{build_file} // '') eq 'makefile'
            && ($config{CPP} // '') eq '$(CC) /EP /C';
    die "foundation profile drift: AMD64 fields\n"
        unless ($target{bn_ops} // '') eq 'SIXTY_FOUR_BIT'
            && ($target{sys_id} // '') eq 'WIN64A'
            && ($target{multilib} // '') eq '-x64';
    die "foundation profile drift: static CRT fields\n"
        unless ($target{lib_cflags} // '') eq '/Zi /Fdossl_static.pdb /MT /Zl'
            && ($target{bin_cflags} // '') eq '/Zi /Fdapp.pdb /MT'
            && ($target{cflags} // '') eq '/Gs0 /GF /Gy';
    die "foundation profile drift: inactive tools\n"
        if $target{RANLIB} || $target{AS} || $target{ASFLAGS}
            || $target{asflags} || $target{asoutflag} || $target{perlasm_scheme}
            || $target{CXX} || $target{OBJCOPY};
    my %required_roles = (CC => 'clang-cl', LD => 'lld-link', AR => 'llvm-lib',
                          RC => 'llvm-rc', MT => 'llvm-mt', PERL => 'perl');
    foreach my $var (sort keys %required_roles) {
        my $value = $cmdvars{$var};
        die "foundation Missing exact H2 $required_roles{$var} binding ($var)\n"
            unless defined($value) && length($value)
                && file_name_is_absolute($value)
                && defined($config{$var}) && $config{$var} eq $value;
    }
    die "foundation profile requires HASHBANGPERL equal to exact H2 PERL binding\n"
        unless defined($cmdvars{HASHBANGPERL})
            && $cmdvars{HASHBANGPERL} eq $cmdvars{PERL}
            && defined($config{HASHBANGPERL})
            && $config{HASHBANGPERL} eq $config{PERL};
    foreach my $var (qw(CXX AS RANLIB OBJCOPY RM CROSS_COMPILE)) {
        die "foundation profile rejects ambient or extra $var\n"
            if $config{$var};
    }
    foreach my $var (qw(ARFLAGS ASFLAGS CFLAGS CXXFLAGS CPPFLAGS CPPDEFINES
                       CPPINCLUDES LDFLAGS LDLIBS MTFLAGS RCFLAGS)) {
        die "foundation profile rejects user flags $var\n"
            if (ref($user{$var}) eq 'ARRAY' && @{$user{$var}})
                || (ref($useradd{$var}) eq 'ARRAY' && @{$useradd{$var}});
    }
    # Configure already appends exactly this release-only definition at 1545.
    die "foundation profile rejects initializer definitions\n"
        unless ref($config{defines}) eq 'ARRAY'
            && @{$config{defines}} == 1 && $config{defines}->[0] eq 'NDEBUG';
    foreach my $var (qw(includes cppflags cflags cxxflags lflags ex_libs)) {
        die "foundation profile rejects initializer flags $var\n"
            if ref($config{$var}) eq 'ARRAY' && @{$config{$var}};
    }
}
# Macro-map consumers are inactive for this exact no-asm/VC-dependency/
# no-strict-warnings profile. Do not generalize this exception to Windows,
# compiler names, prefixes, or other targets. No compiler macros are invented.
my %predefined_C = $foundation_static_amd64_noasm
    ? () : compiler_predefined($config{CROSS_COMPILE}.$config{CC});
my %predefined_CXX = !$foundation_static_amd64_noasm && $config{CXX}
    ? compiler_predefined($config{CROSS_COMPILE}.$config{CXX})
    : ();

